1	/**
2	 * GitLab MR review model — fetches diffs and posts review comments.
3	 * Uses GraphQL for note operations and MR metadata, REST fallback for
4	 * diff content (not available via GraphQL) and approve/unapprove.
5	 * No CLI dependencies.
6	 *
7	 * @module
8	 */
9	// deno-lint-ignore-file no-explicit-any
10	import { z } from "npm:zod@4.6.5";
11	
12	const EXTENSION_NAME = "@webframp/gitlab-review";
13	
14	// =============================================================================
15	// Schemas
16	// =============================================================================
17	
18	const GlobalArgsSchema = z.object({
19	  host: z.string().min(1).describe(
20	    "GitLab hostname (e.g. gitlab.example.com)",
21	  ),
22	  token: z.string().min(1).meta({ sensitive: true }).describe(
23	    "GitLab personal access token",
24	  ),
25	});
26	
27	const DiffFileSchema = z.object({
28	  oldPath: z.string().describe("File path on the old side of the diff"),
29	  newPath: z.string().describe("File path on the new side of the diff"),
30	  diff: z.string().describe("Raw unified diff content for this file"),
31	  newFile: z.boolean().describe("Whether the file was newly added"),
32	  renamedFile: z.boolean().describe("Whether the file was renamed"),
33	  deletedFile: z.boolean().describe("Whether the file was deleted"),
34	});
35	
36	const MrDiffSchema = z.object({
37	  project: z.string().describe("Project the merge request belongs to"),
38	  iid: z.number().describe("Merge request IID"),
39	  title: z.string().describe("Merge request title"),
40	  state: z.string().describe("Merge request state (opened/closed/merged)"),
41	  description: z.string().nullable().describe("Merge request description"),
42	  sourceBranch: z.string().describe("Source branch"),
43	  targetBranch: z.string().describe("Target branch"),
44	  author: z.string().describe("Merge request author's username"),
45	  diffs: z.array(DiffFileSchema).describe("Per-file diff content"),
46	  fetchedAt: z.string().describe("Timestamp the diff was fetched"),
47	  durationMs: z.number().optional().describe(
48	    "Method execution duration in milliseconds",
49	  ),
50	  collectedBy: z.string().optional().describe(
51	    "Extension that collected this data",
52	  ),
53	  truncated: z.boolean().describe(
54	    "Whether GitLab's diff overflow limit was hit, dropping some file diffs",
55	  ),
56	});
57	
58	const ReviewDraftSchema = z.object({
59	  project: z.string().describe("Project the merge request belongs to"),
60	  iid: z.number().describe("Merge request IID"),
61	  body: z.string().describe("Draft review comment body (markdown)"),
62	  createdAt: z.string().describe(
63	    "Timestamp the draft was created or last edited",
64	  ),
65	  fetchedAt: z.string().optional().describe(
66	    "ISO 8601 timestamp when data was fetched",
67	  ),
68	  durationMs: z.number().optional().describe(
69	    "Method execution duration in milliseconds",
70	  ),
