116	// =============================================================================
117	// Helpers
118	// =============================================================================
119	
120	interface ModelContext {
121	  globalArgs: { host: string; token: string };
122	  logger: { info: (msg: string, meta?: Record<string, unknown>) => void };
123	  writeResource: (
124	    specName: string,
125	    instanceName: string,
126	    data: Record<string, unknown>,
127	  ) => Promise<
128	    {
129	      name: string;
130	      specName: string;
131	      kind: string;
132	      dataId: string;
133	      version: number;
134	      size: number;
135	    }
136	  >;
137	  readResource: (
138	    instanceName: string,
139	  ) => Promise<Record<string, unknown> | null>;
140	}
141	
142	function apiUrl(host: string, path: string): string {
143	  return `https://${host}/api/v4${path}`;
144	}
145	
146	function encodeProject(project: string): string {
147	  return encodeURIComponent(project);
148	}
149	
150	function instanceName(prefix: string, project: string, iid: number): string {
151	  return `${prefix}-${encodeURIComponent(project)}-${iid}`;
152	}
153	
154	async function assertMrOpen(
155	  context: ModelContext,
156	  project: string,
157	  iid: number,
158	): Promise<void> {
159	  const diffData = await context.readResource(
160	    instanceName("mrDiff", project, iid),
161	  );
162	  if (!diffData) {
163	    throw new Error(
164	      `No MR data for ${project}!${iid}. Run get_mr_diff first to fetch MR state.`,
165	    );
166	  }
167	  const state = (diffData.state as string) ?? "unknown";
168	  if (state !== "opened") {
169	    throw new Error(
170	      `MR ${project}!${iid} is ${state}. Cannot post or approve a ${state} MR.`,
171	    );
172	  }
173	}
174	
175	async function gitlabFetch(
176	  host: string,
177	  token: string,
178	  path: string,
179	  opts?: RequestInit,
180	): Promise<Response> {
181	  const url = apiUrl(host, path);
182	  const resp = await fetch(url, {
183	    ...opts,
184	    headers: {
185	      "PRIVATE-TOKEN": token,
186	      "Content-Type": "application/json",
187	      ...(opts?.headers || {}),
188	    },
189	  });
190	  if (!resp.ok) {
191	    let body: string;
192	    try {
193	      body = await resp.text();
194	    } catch {
195	      body = "[unable to read response body]";
196	    }
197	    throw new Error(`GitLab API ${resp.status}: ${body}`);
198	  }
199	  return resp;
200	}
201	
202	async function contextFetch(
203	  context: string,
204	  host: string,
205	  token: string,
206	  path: string,
207	  opts?: RequestInit,
208	): Promise<Response> {
209	  try {
210	    return await gitlabFetch(host, token, path, opts);
211	  } catch (err) {
212	    throw new Error(`${context}: ${(err as Error).message}`);
213	  }
214	}
