216	/**
217	 * Remove approval from an MR, idempotently. GitLab's unapprove endpoint returns
218	 * 404 when the caller has no approval to remove; that is the desired end state
219	 * for "request changes", not an error, so we treat it as success. Any other
220	 * non-2xx status still throws. Returns whether an approval was actually removed.
221	 */
222	async function unapproveMr(
223	  ctx: string,
224	  host: string,
225	  token: string,
226	  project: string,
227	  iid: number,
228	): Promise<{ removed: boolean }> {
229	  const url = apiUrl(
230	    host,
231	    `/projects/${encodeProject(project)}/merge_requests/${iid}/unapprove`,
232	  );
233	  const resp = await fetch(url, {
234	    method: "POST",
235	    headers: { "PRIVATE-TOKEN": token, "Content-Type": "application/json" },
236	  });
237	  if (resp.status === 404) {
238	    // Nothing to unapprove — the MR was not approved by this user. Idempotent.
239	    return { removed: false };
240	  }
241	  if (!resp.ok) {
242	    let body: string;
243	    try {
244	      body = await resp.text();
245	    } catch {
246	      body = "[unable to read response body]";
247	    }
248	    throw new Error(`${ctx}: GitLab API ${resp.status}: ${body}`);
249	  }
250	  return { removed: true };
251	}
252	
253	// =============================================================================
254	// GraphQL Client
255	// =============================================================================
256	
257	async function graphqlRequest(
258	  host: string,
259	  token: string,
260	  query: string,
261	  variables?: Record<string, unknown>,
262	): Promise<any> {
263	  const resp = await fetch(`https://${host}/api/graphql`, {
264	    method: "POST",
265	    headers: {
266	      "PRIVATE-TOKEN": token,
267	      "Content-Type": "application/json",
268	    },
269	    body: JSON.stringify({ query, variables }),
270	  });
271	  if (!resp.ok) {
272	    const body = await resp.text();
273	    throw new Error(`GraphQL request failed: ${resp.status} ${body}`);
274	  }
275	  let result: any;
276	  try {
277	    result = await resp.json();
278	  } catch (err) {
279	    const msg = err instanceof Error ? err.message : String(err);
280	    throw new Error(
281	      `GraphQL response from ${host} was not valid JSON: ${msg}`,
282	      { cause: err },
283	    );
284	  }
285	  if (result.errors?.length) {
286	    throw new Error(
287	      `GraphQL errors: ${result.errors.map((e: any) => e.message).join("; ")}`,
288	    );
289	  }
290	  return result.data;
291	}
