293	const MR_METADATA_QUERY = `
294	query mrMetadata($fullPath: ID!, $iid: String!) {
295	  project(fullPath: $fullPath) {
296	    mergeRequest(iid: $iid) {
297	      id iid title state description sourceBranch targetBranch
298	      author { username }
299	    }
300	  }
301	}`;
