303	const CREATE_NOTE_MUTATION = `
304	mutation createNote($noteableId: NoteableID!, $body: String!) {
305	  createNote(input: { noteableId: $noteableId, body: $body }) {
306	    note { id body }
307	    errors
308	  }
309	}`;
