495	        const changesResp = await contextFetch(
496	          `get_mr_diff ${args.project}!${args.iid} changes`,
497	          host,
498	          token,
499	          `/projects/${pid}/merge_requests/${args.iid}/changes?access_raw_diffs=true`,
