522	          diff: (d.diff as string) ?? "",
523	          newFile: (d.new_file as boolean) ?? false,
524	          renamedFile: (d.renamed_file as boolean) ?? false,
525	          deletedFile: (d.deleted_file as boolean) ?? false,
526	        }));
527	
528	        const data = {
529	          project: args.project,
530	          iid: args.iid,
531	          title: mr.title ?? "",
532	          state: (mr.state ?? "unknown").toLowerCase(),
533	          description: mr.description ?? null,
534	          sourceBranch: mr.sourceBranch ?? "",
535	          targetBranch: mr.targetBranch ?? "",
536	          author: mr.author?.username ?? "",
537	          diffs,
538	          fetchedAt: new Date().toISOString(),
539	          truncated,
540	        };
541	
542	        const handle = await context.writeResource(
543	          "mrDiff",
544	          instanceName("mrDiff", args.project, args.iid),
545	          {
546	            ...data,
